create table private.admin_preview_control(
 singleton boolean primary key default true check(singleton),product_id text not null check(product_id='judoju-news'),
 project_ref text not null check(project_ref='nxfpfvsdwbziowkxsxnh'),organization_ref text not null check(organization_ref='qfzgicohgpuogehdyzfx'),
 owner_user_id uuid not null unique references auth.users(id) on delete cascade,
 enabled boolean not null default false,activated_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null,
 decision_sha256 text not null check(decision_sha256 ~ '^[0-9a-f]{64}$'),implementation_manifest_sha256 text not null check(implementation_manifest_sha256 ~ '^[0-9a-f]{64}$'),
 template_sha256 text not null check(template_sha256 ~ '^[0-9a-f]{64}$'),effect_key uuid not null unique,
 owner_email_sha256 text not null default '__OWNER_EMAIL_SHA__'
   check(owner_email_sha256='__OWNER_EMAIL_SHA__'),
 launch_effect uuid not null unique,launched_at timestamptz,host_lease_expires_at timestamptz,
 check(launch_effect=effect_key),
 check((launched_at is null and host_lease_expires_at is null) or
   (launched_at is not null and host_lease_expires_at is not null and isfinite(launched_at) and isfinite(host_lease_expires_at) and launched_at>=activated_at
    and host_lease_expires_at>launched_at and host_lease_expires_at<=expires_at
    and host_lease_expires_at<=launched_at+interval '30 minutes')),
 check(isfinite(activated_at) and isfinite(expires_at) and expires_at>activated_at and expires_at<=activated_at+interval '24 hours')
);
alter table private.admin_preview_control enable row level security;
revoke all on private.admin_preview_control from public,anon,authenticated,service_role;
insert into private.admin_preview_control(product_id,project_ref,organization_ref,owner_user_id,expires_at,decision_sha256,implementation_manifest_sha256,template_sha256,effect_key,launch_effect)
 values('judoju-news','nxfpfvsdwbziowkxsxnh','qfzgicohgpuogehdyzfx','__OWNER_UUID__'::uuid,'__EXPIRES_AT__'::timestamptz,'__DECISION_SHA__','__IMPLEMENTATION_SHA__','__TEMPLATE_SHA__','__EFFECT_UUID__'::uuid,'__EFFECT_UUID__'::uuid);
-- READ ONLY-compatible fence. All authority queries require fresh READ COMMITTED statement snapshots.
create function private.admin_preview_authority(p_user uuid,p_session uuid,p_hash text,p_require_app boolean) returns jsonb language plpgsql volatile security invoker set search_path='' as $function$
declare result jsonb;denied constant jsonb:='{"authorized":false,"session":null}'::jsonb;
begin
 if p_user is null or p_session is null or p_require_app is null
   or (not p_require_app and p_hash is not null) or (p_hash is not null and p_hash!~'^[0-9a-f]{64}$')
   or pg_catalog.current_setting('transaction_isolation')<>'read committed' then return denied;end if;
 perform pg_catalog.pg_advisory_xact_lock_shared(1246704725,1127380914);
 if pg_catalog.current_setting('transaction_isolation')<>'read committed' then return denied;end if;
 -- A new VOLATILE statement snapshot AFTER the advisory wait; no pre-lock ciphertext is reused.
 with t as materialized(select pg_catalog.clock_timestamp() as ts), authority as materialized(
   select 1 from private.admin_preview_control c
   join auth.users u on u.id=c.owner_user_id
   join auth.sessions a on a.user_id=u.id and a.id=p_session
   join private.admin_memberships m on m.user_id=u.id and m.active
   cross join t
   where c.singleton and c.enabled and c.owner_user_id=p_user
     and c.product_id='judoju-news' and c.project_ref='nxfpfvsdwbziowkxsxnh' and c.organization_ref='qfzgicohgpuogehdyzfx'
     and c.activated_at<=t.ts and c.expires_at>t.ts and c.launch_effect=c.effect_key
     and c.launched_at is not null and c.launched_at<=t.ts and c.host_lease_expires_at is not null and c.host_lease_expires_at>t.ts
     and u.email_confirmed_at is not null and u.is_anonymous=false and u.is_sso_user=false and u.deleted_at is null
     and (u.banned_until is null or u.banned_until<=t.ts) and (a.not_after is null or a.not_after>t.ts)
     and pg_catalog.encode(extensions.digest(pg_catalog.convert_to(pg_catalog.lower(pg_catalog.btrim(u.email)),'UTF8'),'sha256'),'hex')=c.owner_email_sha256
     and u.raw_app_meta_data->>'app_role'='admin' and u.raw_app_meta_data->>'product_id'='judoju-news'
     and u.raw_app_meta_data->>'provider'='email' and u.raw_app_meta_data->'providers'='["email"]'::jsonb
     and (select count(*) from auth.identities i where i.user_id=u.id)=1
     and exists(select 1 from auth.identities i where i.user_id=u.id and i.provider='email')
     and exists(select 1 from private.runtime_identity r where r.singleton and r.product_id='judoju-news' and r.environment='preview' and r.bootstrap_id is null)
     and exists(select 1 from judoju_control.environment_identity e where e.singleton and e.product_id='judoju-news' and e.environment='dev' and e.project_ref=c.project_ref and e.organization_ref=c.organization_ref)
 ), current_cap as materialized(
   select x.ciphertext,x.user_id,x.auth_session_id,x.expires_at from private.admin_sessions x cross join t
   where p_require_app and exists(select 1 from authority) and x.user_id=p_user and x.auth_session_id=p_session
     and x.revoked_at is null and x.expires_at>t.ts and (p_hash is null or x.capability_hash=p_hash)
 ), permitted as materialized(select exists(select 1 from authority) and (not p_require_app or exists(select 1 from current_cap)) as ok)
 select pg_catalog.jsonb_build_object('authorized',p.ok,'session',case when p.ok and p_require_app and p_hash is not null then
   (select pg_catalog.jsonb_build_object('ciphertext',x.ciphertext,'user_id',x.user_id,'auth_session_id',x.auth_session_id,'expires_at',x.expires_at) from current_cap x limit 1) else null end)
 into result from permitted p;
 return result;
end
$function$;
revoke execute on function private.admin_preview_authority(uuid,uuid,text,boolean) from public,anon,authenticated,service_role;
create or replace function private.active_admin_user(p_user uuid,p_session uuid) returns boolean language plpgsql volatile security invoker set search_path='' as $function$
begin
 return (private.admin_preview_authority(p_user,p_session,null,false)->>'authorized')::boolean;
end
$function$;
revoke execute on function private.active_admin_user(uuid,uuid) from public,anon,authenticated,service_role;
create or replace function private.is_admin() returns boolean language plpgsql stable security invoker set search_path='' as $function$
declare c jsonb;u uuid;s uuid;
begin
 if private.caller_role()<>'authenticated' then return false;end if;
 c:=coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb;
 if coalesce(c->>'sub','')!~'^[0-9a-f-]{36}$' or coalesce(c->>'session_id','')!~'^[0-9a-f-]{36}$' then return false;end if;
 begin u:=(c->>'sub')::uuid;s:=(c->>'session_id')::uuid;exception when invalid_text_representation then return false;end;
 return (private.admin_preview_authority(u,s,null,true)->>'authorized')::boolean;
end
$function$;
revoke execute on function private.is_admin() from public,anon,authenticated,service_role;
create or replace function public.m1_read_admin_session(p_hash text) returns jsonb language plpgsql volatile security definer set search_path='' as $function$
declare u uuid;s uuid;r jsonb;
begin
 perform private.assert_server();perform private.assert_initialized();
 -- Identity hint only. Exact hash, current ciphertext and expiry are reread inside the locked authority query.
 select x.user_id,x.auth_session_id into u,s from private.admin_sessions x where x.capability_hash=p_hash;
 if not found then return null;end if;
 r:=private.admin_preview_authority(u,s,p_hash,true);
 if (r->>'authorized')::boolean is distinct from true then return null;end if;
 return nullif(r->'session','null'::jsonb);
end
$function$;
revoke execute on function public.m1_read_admin_session(text) from public,anon,authenticated,service_role;
