ha256":"902a1456d963d0cf6025eaba686eebf5d3afc73d93ebaff71ac7b533824922b6","securityDefiner":true,"volatility":"v","config":["search_path=\"\""],"apiRoles":[["anon",false],["authenticated",false],["service_role",false]]},{"name":"public.reservation_list","signature":"uuid","sha256":"ce3e0480eaf51003abfb82ba06ff0eb70b14ef657207ff0435d888e03a56c89c","securityDefiner":true,"volatility":"v","config":["search_path=\"\""],"apiRoles":[["anon",false],["authenticated",false],["service_role",false]]},{"name":"public.reservation_request_status","signature":"uuid","sha256":"ea79b9d1ae7788aca26a9f35871b0cf81a5a8d1006b1ae21d9fcfad9bb7c20d6","securityDefiner":true,"volatility":"v","config":["search_path=\"\""],"apiRoles":[["anon",false],["authenticated",false],["service_role",false]]},{"name":"public.resolve_issue","signature":"uuid","sha256":"4d63693f8c31c316d9770409951a3659cae185a31162bd35c54a3f47b71dad6f","securityDefiner":true,"volatility":"v","config":["search_path=\"\""],"apiRoles":[["anon",false],["authenticated",false],["service_role",false]]}]'::jsonb) loop
  oid_value:=to_regprocedure((f->>'name')||'('||(f->>'signature')||')');
  expected_sha:=case f->>'name' when 'private.active_admin_user' then '2ddc2d7c2163e6ddeaf349e10c919f5cffa6a469b0c17c8076fe56ab2114767a' when 'private.is_admin' then '5520e17b8f844679726928cc892d93035a074d25504f394ade2bf12a068f8939' when 'public.m1_read_admin_session' then '6fa80cb2d0f9ba26b278464bf63e4764cfde42e5585f1fef18d7096e5c601c18' else f->>'sha256' end;
  if oid_value is null or encode(extensions.digest(convert_to(pg_get_functiondef(oid_value),'UTF8'),'sha256'),'hex') is distinct from expected_sha
   or not exists(select 1 from pg_proc where oid=oid_value and proowner='postgres'::regrole
    and prosecdef=(f->>'securityDefiner')::boolean and provolatile=(case when f->>'name'='private.active_admin_user' then 'v' else f->>'volatility' end)::"char"
    and to_jsonb(proconfig)=f->'config') then raise exception 'ADMIN_PREVIEW_DEFINITION_POSTCHECK';end if;
 end loop;
 oid_value:=to_regprocedure('private.admin_preview_authority(uuid,uuid,text,boolean)');
 if oid_value is null or not exists(select 1 from pg_catalog.pg_proc where oid=oid_value and proowner='postgres'::regrole and not prosecdef and provolatile='v' and proconfig=ARRAY['search_path=""'])
   or encode(extensions.digest(convert_to(pg_get_functiondef(oid_value),'UTF8'),'sha256'),'hex')<>'034d5d73dafd844b182a78316fca30ec16f02a6315c88badd3f6a87c75e42f4f'
   or exists(select 1 from pg_catalog.pg_proc p cross join lateral pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a where p.oid=oid_value and a.grantee=0 and a.privilege_type='EXECUTE')
   or has_function_privilege('anon',oid_value,'EXECUTE') or has_function_privilege('authenticated',oid_value,'EXECUTE') or has_function_privilege('service_role',oid_value,'EXECUTE')
   then raise exception 'ADMIN_PREVIEW_HELPER_POSTCHECK';end if;
end $function_post$;
